def build(bank,sets):
 if any(s['id']=='D2-C' for s in sets):return
 new=[]
 for n,line in enumerate(DATA.strip().splitlines(),1):
  topic,slides,prompt,correct,*opts=line.split('|');options=[]
  for i,raw in enumerate(opts):
   text,reason=raw.split('^');options.append(dict(id=chr(97+i),text=text,reason=reason))
  new.append(dict(id=f'D2-C-{n:02}',version=1,domain='concept' if n<=25 else 'implementation',topic=topic,type='multiple' if len(correct)>1 else 'single',prompt=prompt,options=options,correct=list(correct),explanation=' '.join(o['reason'] for o in options if o['id'] in correct),source=SOURCES[topic],lecture='Day 2 · 슬라이드 '+slides,lab='Day 2 · 슬라이드 1~40 범위',authorship='자체 제작 · Microsoft 공식 시험/평가 문항 아님',difficulty='종합 응용',reviewedAt='2026-10-27',slideRefs=[int(s) for s in slides.split(',')]))
 assert len(new)==40,len(new)
 bank.extend(new)
 first=dict(id='D2-C',hidden=True,title='Day 2 슬라이드 1~40 이해도 점검',day=2,minutes=50,kind='practice',phase='day-review',expectedCount=40,includeInCumulative=False,questionIds=[q['id'] for q in new])
 # One question from each pair of coverage topics; no duplicates within the mixed review.
 day1=[3,5,7,9,13,14,15,16,17,18,21,22,27,30,32,35]
 day2=[2,3,5,8,9,11,15,18,21,24,26,30,34,36,37,39]
 mixed=[f'D1-C-{n:02}' for n in day1]+[f'D2-C-{n:02}' for n in day2]+[f'D2-B-{n}' for n in ['01-2','02-2','03-1','04-2','05-1','06-2','07-2','08-2','09-2','10-2']]
 random.Random(9011227).shuffle(mixed)
 second=dict(id='D12-C',title='Day 1+2 종합 점검 · 전체 범위',day=2,minutes=55,kind='practice',phase='day-review',expectedCount=42,includeInCumulative=False,questionIds=mixed)
 pos=next(i for i,s in enumerate(sets) if s['id']=='D2-B')+1;sets[pos:pos]=[first,second]

def write_guides(bank,sets):
 byid={q['id']:q for q in bank}
 for id,file in [('D2-C','day2-slides-1-40-review.md'),('D12-C','day1-day2-mixed-review.md')]:
  s=next(s for s in sets if s['id']==id);lines=['# '+s['title'],'',f"{s['expectedCount']}문항 · {s['minutes']}분 · 별도 순위 · 기존 누적 순위 합산 제외",'', '범위: Day 2 슬라이드 1~40.' if id=='D2-C' else '범위: Day 1 전체 + Day 2 전체(슬라이드 1~98, 3강·7강·8강·Lab 03~07). Day 1 핵심 16문항, Day 2 전반 16문항, 후반 프롬프트·채팅 앱 10문항을 혼합합니다. 인증·API 호출, temperature·출력 상한, 역할·대화 이력·컨텍스트 관리, 근거·외부 지시·구조화 출력까지 포함합니다.','']
  for n,qid in enumerate(s['questionIds'],1):
   q=byid[qid];lines+=['## '+str(n)+'. '+qid+' · '+q['topic'],'',q['prompt'],'','교안 연결: '+q['lecture'],'']
   if q.get('code'):lines+=['```python',q['code'],'```','']
   lines += [o['id'].upper()+'. '+o['text'] for o in q['options']]
   lines += ['','정답: '+', '.join(q['correct']),'',q['explanation'],'']
   lines += ['- '+o['id'].upper()+': '+o['reason'] for o in q['options']]
   lines += ['','[공식 개념 근거]('+q['source']+')','']
  (ROOT/'docs'/file).write_text('\n'.join(lines)+'\n')
if __name__=='__main__':
 p=ROOT/'content/questions.json';s=ROOT/'content/sets.json';bank=json.loads(p.read_text());sets=json.loads(s.read_text());build(bank,sets);write_guides(bank,sets)
 p.write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n');s.write_text(json.dumps(sets,ensure_ascii=False,indent=2)+'\n')
